import json
from types import SimpleNamespace
from unittest.mock import patch
from drm_copilot_discovery.analyzer.pipeline import run_inventory
counts = {'equality': 0, 'analysis': 0}
class Mislabelled(str):
    def __eq__(self, other):
        counts['equality'] += 1
        return True
class Adapter:
    identifier = Mislabelled('dotnet')
    def analyze(self, capture):
        counts['analysis'] += 1
        return 'analysis'
class Registry:
    def select(self, profile, *, analyzer_ids=None):
        return (Adapter(),)
with patch('drm_copilot_discovery.analyzer.registry.normalized_analyzer_ids', return_value=('repository',)), patch('drm_copilot_discovery.analyzer.emitter.inventory_result', return_value='reached-emitter'):
    result = run_inventory(SimpleNamespace(profile=object()), timestamp='unused', author_or_agent=None, catalog=None, analyzer_registry=Registry())
print(json.dumps({'boundary': 'run_inventory returned-ID validation only; selector normalization and emitter replaced by fixed sentinels', 'requested': ['repository'], 'returned_identifier_text': str(Adapter.identifier), 'returned_identifier_exact_str': type(Adapter.identifier) is str, 'result': result, 'counts': counts}))
